    ["The rules are too long together. Keep them under {max} characters in all."] = "ルールの合計が長すぎます。全体で{max}文字未満にしてください。",
    ["This text is too long. Keep it under {max} characters."] = "この文章は長すぎます。{max}文字未満にしてください。",
