    ["{field}: {message}"] = "{field}：{message}",
    ["In use now"] = "使用中",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "各会話オプションにどう答えるかを指示します。オプションごとに個別のプロンプトがあります。変更は次の返答から反映され、再起動は不要です。",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "キャラクターがゲームから得る事実と、安全フィルターの短いリストはここでは編集できません。Convai のプロンプトは Convai 側にあります。",
    ["Mistral and Local AI"] = "Mistral と Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "LiteとStandardは、Local AI の2つのモデルサイズです。「成人向けオン」は成人向けコンテンツがオンの間に使われます。",
    ["Your Custom models and APIs"] = "あなたのカスタムモデルとAPI",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "会話プロバイダーにカスタムを選び、モデルを設定すると、ここにカスタムモデルが表示されます。",
    ["From {min} to {max}."] = "{min}から{max}まで。",
