    ["Save current party"] = "現在のパーティーを保存",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "{name}として保存しました。その下の「パーティーを招待」を押すと、再び招待できます。",
    ["Saved party: {name}"] = "保存済みパーティー：{name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "現在のパーティーにいるキャラクターを、コピーや自分のキャラクターを含めて、ワンプッシュで再び招待できるパーティーとして保存します。名前は パーティー 1、パーティー 2 のように付けられ、下に表示されます。\n\n保存できるパーティーは最大{count}個です。",
    ["Spawn"] = "招待",
    ["Spawn party"] = "パーティーを招待",
    ["That party no longer exists."] = "そのパーティーはもう存在しません。",
    ["The characters of this party: {names}."] = "このパーティーのキャラクター：{names}。",
    ["The party could not be saved."] = "パーティーを保存できませんでした。",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "このメニューにはテキスト入力欄がないため、パーティーは名前を保持します。Mod Configuration Menuには入力欄があります。その検索欄に名前を入力してください。",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "新しい名前を上部の検索欄（Mod Configuration Menu）に入力し、「名前を変更」を押してください。Native Settings UIにはテキスト入力欄がないため、そこではパーティーは名前を保持します。",
    ["Type the new name in the Search box first, then press Rename."] = "まず新しい名前を検索欄に入力し、「名前を変更」を押してください。",
    ["Update"] = "更新",
    ["Update with current party"] = "現在のパーティーで更新",
    ["You can keep {count} saved parties. Delete one first."] = "保存済みパーティーは{count}個まで保持できます。先に1つ削除してください。",
    ["Your party is empty. Invite someone first."] = "パーティーに誰もいません。先に誰かを招待してください。",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "保存済みパーティーをディスクに書き込めなかったため、ゲームを終了するまでしか保持されません。",
    ["that character model is unavailable"] = "そのキャラクターモデルは利用できません",
    ["the invitation was refused"] = "招待は拒否されました",
    ["{name} ({count})"] = "{name}（{count}）",
    ["{name} ({reason})"] = "{name}（{reason}）",
    ["{name} deleted."] = "{name}を削除しました。",
