    ["{party}: inviting {names}."] = "{party}：{names}を招待中。",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "{name}をお気に入りに追加します。ページ 1 の先頭と、スマホのチャットタブの先頭に表示されます。アップデートでは変更されません。",
    ["Favorites"] = "お気に入り",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "ここに表示されるお気に入りは最初の{count}件だけです。残りは下のリストにあります。",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "ページ {page}/{pages}: {kind} {first}～{last}。",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "押すとページ {page}/{pages} に移動します: {kind} {first}～{last}。",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "{name}をお気に入りから外します。下のリストでの位置はそのままです。",
    ["This is the first page."] = "ここが最初のページです。",
    ["This is the last page."] = "ここが最後のページです。",
    ["characters"] = "キャラクター",
    ["entries"] = "項目",
    ["models"] = "モデル",
    ["{count} more favorites"] = "ほか{count}件のお気に入り",
    ["{name} is now a favorite. Favorites are at the top of page 1."] = "{name}をお気に入りに追加しました。お気に入りはページ 1 の先頭に表示されます。",
    ["Favorite"] = "お気に入り",
    ["That look is not one of this character’s."] = "その見た目はこのキャラクターのものではありません。",
    ["That choice is not available."] = "その選択肢は利用できません。",
    ["The editor keeps choices for {max} characters. Reset one first."] = "エディターに保存できるのは{max}人分です。先に1人分をリセットしてください。",
    ["Usual look"] = "通常の見た目",
    ["Home clothes: tank top, boxer shorts, flip-flops"] = "家着：タンクトップ、ボクサーパンツ、ビーチサンダル",
    ["No jacket"] = "ジャケットなし",
    ["No jacket and harness"] = "ジャケットなし、ハーネス着用",
    ["Home clothes: shirt and trousers"] = "家着：シャツとズボン",
    ["Home clothes: tank top and trousers"] = "家着：タンクトップとズボン",
    ["Hooded jacket"] = "フード付きジャケット",
    ["Home clothes: t-shirt and trousers"] = "家着：Tシャツとズボン",
    ["Collar down"] = "襟を下ろす",
    ["Valentino look"] = "ヴァレンティノの見た目",
    ["Suit"] = "スーツ",
    ["Club night, no jacket"] = "クラブの夜、ジャケットなし",
    ["Solo look"] = "ソロの見た目",
    ["Date night"] = "デートの夜",
    ["T-shirt"] = "Tシャツ",
    ["Vest"] = "ベスト",
    ["Paradise look"] = "パラダイスの見た目",
    ["Bartender"] = "バーテンダー",
    ["Dress without the fur coat"] = "ファーコートなしのドレス",
    ["Trench coat"] = "トレンチコート",
    ["Without the coat"] = "コートなし",
    ["CEO look with coat"] = "CEOの見た目（コート付き）",
    ["CEO look"] = "CEOの見た目",
    ["Pyjamas"] = "パジャマ",
    ["Valentino look, collar open"] = "ヴァレンティノの見た目、襟を開けた姿",
    ["Vest and rucksack"] = "ベストとリュック",
    ["Arasaka work clothes, no jacket"] = "アラサカの作業服、ジャケットなし",
    ["Red parade dress"] = "赤いパレードドレス",
    ["Red parade dress with bracelets"] = "腕輪つきの赤いパレードドレス",
    ["Party dress"] = "パーティードレス",
    ["Tank top"] = "タンクトップ",
    ["Street clothes"] = "普段着",
    ["Merc look"] = "傭兵の見た目",
    ["Go back to the usual look and moves for {name}? Your choices on this part are removed."] = "{name}の通常の見た目と動きに戻しますか？この項目での選択は削除されます。",
    ["Back to the usual look and moves."] = "通常の見た目と動きに戻しました。",
    ["Choices for how this character looks and moves. They work with every conversation option, Convai included, except the reply length."] = "このキャラクターの見た目と動きの設定です。返答の長さを除き、Convaiを含むすべての会話オプションで機能します。",
    ["Outfit"] = "衣装",
    ["Automatic follows the “Companions change outfits” setting in the game: day and night looks, now and then a change, and casual clothes at home. A look you pick is worn all the time. Only your own companions and residents are dressed, and they change while nobody is looking. Characters the game places are never changed."] = "自動は、ゲーム内の「コンパニオンの衣装替え」設定に従います。昼と夜の見た目、時々の衣装替え、家でのくつろぎ着があります。選んだ見た目は常に着用されます。着替えるのは自分のコンパニオンと住人だけで、誰も見ていないときに着替わります。ゲームが配置したキャラクターは決して変更されません。",
    ["This character has only one look in the game files, so there is no outfit to choose."] = "このキャラクターはゲームファイル内の見た目が1つだけのため、選べる衣装はありません。",
    ["Talking gestures"] = "会話中のジェスチャー",
    ["How the hands move while they speak a longer reply."] = "長めの返答を話すときの手の動きです。",
    ["Normal"] = "通常",
    ["Calm: smaller gestures, not as often"] = "控えめ：小さめのジェスチャー、回数は少なめ",
    ["Lively: bigger gestures, more often"] = "活発：大きめのジェスチャー、回数は多め",
    ["None: the hands stay at rest"] = "なし：手は静止したまま",
    ["Nod while you talk to them"] = "話しかけている間に頷く",
    ["A small nod now and then while you speak."] = "あなたが話している間、ときどき小さく頷きます。",
    ["Idle moves"] = "待機中の動き",
    ["What they do now and then while they stand beside you."] = "そばに立っている間、ときどき行う動きです。",
    ["Plain stances only, no props like a cup or a cigarette"] = "シンプルな立ち姿のみ。カップやタバコなどの小道具は使いません。",
    ["None: they keep the stance they have"] = "なし：今の立ち姿のまま",
    ["Sit down and take a place"] = "座って席につく",
    ["Takes a seat beside you when you sit, and a seat or a spot in your flat at home. Switched off, they stay on their feet beside you."] = "あなたが座るとそばに座り、アパートでも座席か決まった場所につきます。オフにすると、そばに立ったままになります。",
    ["Comment on fights and loot"] = "戦闘と戦利品についてコメントする",
    ["Switched off, they say nothing about fights or about what you pick up."] = "オフにすると、戦闘や拾ったアイテムについては何も言いません。",
    ["Reply length"] = "返答の長さ",
    ["Shorter: up to about {words} words"] = "短め：約{words}語まで",
    ["Very short: up to about {words} words"] = "とても短め：約{words}語まで",
    ["A saved choice counts within a few seconds. Clothes change when nobody is looking."] = "保存した選択は数秒以内に反映されます。衣装は誰も見ていないときに着替わります。",
    ["Look and moves"] = "見た目と動き",
    ["Shift"] = "Shift",
    ["Ctrl"] = "Ctrl",
    ["Alt"] = "Alt",
    ["Hold Shift, Ctrl or Alt while you press a key to set a combination such as Shift+F5. A combination runs only with exactly those keys held, and a plain key does not run while one is held. In the game Shift sprints, Ctrl dodges and Alt opens the weapon wheel, so V does that too."] = "キーを押すときに Shift、Ctrl、Alt を押したままにすると、Shift+F5 のような組み合わせを設定できます。組み合わせは、ちょうどそのキーを押している間だけ動作し、単独のキーはいずれかを押している間は動作しません。ゲームでは Shift でダッシュ、Ctrl で回避、Alt でウェポンホイールが開くため、V もそれを行います。",
    ["Disk space"] = "ディスク容量",
    ["Your {drive} drive is almost full ({free} GB free). Free space so the mod can save logs and memories."] = "ドライブ {drive} の空きがわずか（残り{free}GB）です。ログと記憶を保存できるよう、空けてください。",
    ["An input marked (!) looks like a loopback or virtual input, such as Stereo Mix, CABLE Output or a mixer’s Out. It can carry other apps’ sound, for example the far side of a call, so the mod never picks one by itself."] = "(!) の付いた入力は、Stereo Mix、CABLE Output、ミキサーの出力などのループバックまたは仮想入力に見えます。通話相手の音など、ほかのアプリの音も入ることがあるため、MODは自動で選ぶことはありません。",
    ["The input you chose looks like it carries PC sound, not only your voice. If characters hear your calls, choose your real microphone."] = "選んだ入力は、声だけでなく PC の音も拾っているように見えます。キャラクターに通話が聞こえているなら、実際のマイクを選んでください。",
    ["{name} looks like it carries PC sound, such as a call, not only your voice. Choose your real microphone in Settings > Voices > Microphone."] = "{name} は、声だけでなく通話などの PC の音も拾っているように見えます。設定 > 音声 > マイク で実際のマイクを選んでください。",
    ["No API key is saved yet. Copy your key from your provider, press Paste API key, then test again."] = "APIキーはまだ保存されていません。プロバイダーからキーをコピーし、「APIキーを貼り付け」を押してから、もう一度テストしてください。",
    ["Add"] = "追加",
    ["Deletes this free setup: the endpoint URL, the model ID and the API key saved with it."] = "保存済みのこの無料設定（エンドポイントURL、モデルID、APIキー）を削除します。",
    ["Allow Local AI to use RAM"] = "Local AI による RAM の使用を許可",
    ["Off: when the Local AI model you chose does not fit the free graphics memory beside the game, a smaller model that fits is loaded instead, with one notice.\n\nOn: your chosen model is kept and part of it runs from system memory (RAM) on the processor. Replies are slower, and you are told once. It needs enough free RAM, and the game may have less processor time."] = "オフ：選んだ Local AI モデルがゲームと並んで空きグラフィックメモリに収まらない場合は、収まる小型モデルが代わりに読み込まれ、通知が1回表示されます。\n\nオン：選んだモデルはそのまま保たれ、一部がシステムメモリ（RAM）上でプロセッサを使って動作します。返信は遅くなり、その旨が1回通知されます。十分な空き RAM が必要で、ゲームに割り当てられるプロセッサ時間が減ることがあります。",
    ["Using {model}"] = "{model} を使用中",
    ["{model} is in use because the model you chose did not fit beside the game. Your choice is unchanged."] = "選んだモデルはゲームと並べると収まらないため、{model} を使用しています。選択は変更されていません。",
    ["Local AI is keeping {model} as you allowed, with part of it in system memory. Replies will be slower."] = "Local AI は許可された設定どおり {model} を維持し、一部をシステムメモリで動かしています。返信は遅くなります。",
    ["Choosing Convai or Google Gemini turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Convai または Google Gemini を選ぶとオフになります。Voxtral は併用されません：Voxtral の音声は Pocket に切り替わり、オフにすると元に戻ります。",
    ["Convai could not sign in. Try again in a moment, or choose Google Gemini or Local AI in Settings > Conversation provider."] = "Convai にサインインできませんでした。しばらくしてから再度お試しいただくか、設定 > 会話プロバイダー で Google Gemini または Local AI を選択してください。",
    ["Convai is answering right now, so these changes have no effect yet. Choose Google Gemini, Local AI or Custom as the conversation provider in the settings."] = "Convai が今応答中のため、これらの変更はまだ反映されません。設定で会話プロバイダーとして Google Gemini、Local AI、カスタムのいずれかを選んでください。",
    ["Convai: Google Gemini has no key yet"] = "Convai：Google Gemini キーは未設定",
    ["Copy your Mistral API key first, then press Add. It fills in the endpoint URL and the model ID for Mistral (Ministral 8B) and saves your key from the clipboard. The same key powers the Voxtral cloud voice.\n\nNew Mistral accounts may not get a free API key any more."] = "まず Mistral の API キーをコピーしてから Add を押してください。Mistral (Ministral 8B) のエンドポイントURLとモデルIDが入力され、クリップボードのキーが保存されます。同じキーで Voxtral のクラウド音声も使えます。\n\n新規の Mistral アカウントでは、無料の API キーがもう得られない場合があります。",
    ["Copy your key from Google AI Studio first (aistudio.google.com/apikey, a Google account is enough, no card). It is read from the clipboard once and saved on this computer.\n\nThe free plan has a daily limit of about 500 replies, is not offered in every country, and Google may use free-plan chats to improve its products."] = "まず Google AI Studio でキーをコピーしてください (aistudio.google.com/apikey、Google アカウントがあれば十分、カードは不要)。クリップボードから一度だけ読み取られ、このコンピューターに保存されます。\n\n無料プランには1日約500回の返答の上限があり、すべての国で提供されているわけではありません。また、Google は無料プランのチャットを製品の改善に使うことがあります。",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with Google Gemini, Local AI and Custom, not Convai. Changes apply from the next reply."] = "ブラウザーで、キャラクターの経歴、話し方、話し方のルール、記憶と、AI の選択肢ごとのプロンプトを編集したり、自分のキャラクターを作ったりできます。\n\nGoogle Gemini、Local AI、カスタムで動作します。Convai では動作しません。変更は次の返答から反映されます。",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with Google Gemini, Local AI and Custom, not Convai. Changes apply from the next reply."] = "ブラウザーで、キャラクターの経歴、ルール、記憶と、AI の選択肢ごとのプロンプトを編集できます。\n\nGoogle Gemini、Local AI、カスタムで動作します。Convai では動作しません。変更は次の返答から反映されます。",
    ["From Convai or Google Gemini, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Convai または Google Gemini からオンにすると Local AI が選ばれます。Local AI がインストールされていない場合はカスタムが選ばれます。Local AI では、収まる最大の無検閲モデルも選ばれます。オフにすると、以前の選択に戻ります。",
    ["Google Gemini (free plan)"] = "Google Gemini（無料プラン）",
    ["Google Gemini API key"] = "Google Gemini API キー",
    ["Google Gemini has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Google Gemini のキーがまだないため、Convai を使用します。設定 > 会話プロバイダーでキーを追加してください。",
    ["Google Gemini replies are spoken by a local voice instead of the Convai cloud voice."] = "Google Gemini の返答は、Convai のクラウド音声の代わりにローカル音声で読み上げられます。",
    ["Google Gemini: key not accepted"] = "Google Gemini：キーが受け付けられません",
    ["The service is not available in your region."] = "お住まいの地域ではサービスをご利用いただけません。",
    ["Google accepted the key."] = "Googleがキーを承認しました。",
    ["Google did not accept this key. Check it in Google AI Studio, then Remove it and Add the right one."] = "Googleがこのキーを承認しませんでした。Google AI Studioで確認してから、削除を押し、正しいキーを追加してください。",
    ["Google accepted the key, but the free allowance is used up for now."] = "Googleがキーを承認しましたが、無料枠は今のところ使い切られています。",
    ["The key is saved, but Google Gemini is not available in your region."] = "キーは保存されましたが、お住まいの地域ではGoogle Geminiをご利用いただけません。",
    ["The key is saved, but Google could not be reached to check it."] = "キーは保存されましたが、確認のためGoogleに接続できませんでした。",
    ["Google Gemini: rate limited for a minute"] = "Google Gemini：1分間制限中",
    ["Google Gemini: free allowance used up for today"] = "Google Gemini：本日の無料枠を使い切りました",
    ["Google Gemini: not available in your region"] = "Google Gemini：お住まいの地域では利用できません",
    ["Google did not accept your Gemini key. Check it in Google AI Studio and add it again."] = "Google が Gemini キーを承認しません。Google AI Studio で確認し、再度追加してください。",
    ["Your free Gemini allowance for today is used up. It resets at {time}. Use Convai or Local AI."] = "本日の無料 Gemini 枠を使い切りました。{time} にリセット。Convai か Local AI をご利用ください。",
    ["Your free Gemini allowance for today is used up. It resets tomorrow. Use Convai or Local AI."] = "本日の無料 Gemini 枠を使い切りました。明日リセット。Convai か Local AI をご利用ください。",
    ["Google Gemini is rate limiting you. Wait a minute, then try again."] = "Google Gemini の利用が制限中です。1分待ってから再試行してください。",
    ["Google Gemini is not available in your region. Use Convai or Local AI."] = "Google Gemini はお住まいの地域で利用できません。Convai か Local AI をご利用ください。",
    ["Google Gemini is busy or had an error. Wait a minute, then try again."] = "Google Gemini が混雑中かエラーです。1分待ってから再試行してください。",
    ["Google Gemini could not be reached. Check your internet connection, then try again."] = "Google Gemini に接続できません。インターネットを確認し、再試行してください。",
    ["The Gemini model is not available right now. Try again later or use Local AI."] = "Gemini モデルは現在利用できません。後で再試行するか、Local AI をご利用ください。",
    ["Google Gemini: model unavailable"] = "Google Gemini：モデルが利用できません",
    ["Mistral (your key)"] = "Mistral（自分のキー）",
    ["Requires a Mistral key (add it with the Mistral preset on the Custom endpoint page)"] = "Mistral キーが必要です（Custom endpoint のページにある Mistral プリセットで追加してください）",
    ["The conversation limit has been reached. Try again later, or choose Local AI or Google Gemini in Settings > Conversation provider."] = "会話の上限に達しました。しばらくしてから再度お試しいただくか、設定 > 会話プロバイダー で Local AI または Google Gemini を選んでください。",
    ["The longest reply, in words. Works with Google Gemini, Local AI and Custom, not Convai."] = "語数で示した返答の最大長です。Google Gemini、Local AI、Customで機能し、Convaiでは機能しません。",
    ["They join as a copy of the model they were made from. They talk with Google Gemini, Local AI or Custom; with Convai they talk as an ordinary person."] = "元になったモデルのコピーとして仲間になります。Google Gemini、Local AI、カスタムで会話でき、Convai では普通の人として話します。",
    ["Today’s Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Convai 今日の分を使用済み。\n{time}にリセットされます。Local AI（無制限）か Google Gemini（ご自身のキー）",
    ["Today’s Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Convai 今日の分を使用済み。\nLocal AI（無制限）か Google Gemini（ご自身のキー）",
    ["Today’s {limit} Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Convai 今日の{limit}回分を使用済み。\n{time}にリセットされます。Local AI（無制限）か Google Gemini（ご自身のキー）",
    ["Today’s {limit} Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Convai 今日の{limit}回分を使用済み。\nLocal AI（無制限）か Google Gemini（ご自身のキー）",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Google Gemini, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "コンテンツパック {name} をオンまたはオフにします。パックはキャラクターの話し方を変えます。プロンプトの変更は Google Gemini、Local AI、カスタムで機能します。Convai では、そのワールドルールと専用の Convai キャラクターが適用されます。切り替えは次の返答から、新しい名前は再起動後に反映されます。",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Google Gemini, Local AI and Custom)."] = "ゲームが各キャラクターに今この瞬間について伝える内容です。キャラクターは会話に合うときだけ言及します。\n\nオフの項目は、すべての会話プロバイダー（Convai、Google Gemini、Local AI、カスタム）から外されます。",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "コンパニオンの返答を誰が生成するか。変更は会話が実行中でなくなるまで保留されます。\n\nConvai の無料プランは設定が不要で、より良い返答が得られます。Convai APIキーは自分のキーを使います。Google Gemini は自分の無料キーを使い、記憶はこのコンピューターに残ります。\n\nGoogle Gemini、Local AI、カスタムを使う場合、Convai のクラウド音声はローカル音声に置き換えられます。音声認識はこのコンピューターで行われるため、音声キーが機能します。",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "コンパニオンの返答を誰が生成するか。変更は会話が実行中でなくなるまで保留されます。\n\nConvai の無料プランは設定が不要で、より良い返答が得られます。Convai APIキーは自分のキーを使います。Google Gemini は自分の無料キーを使い、記憶はこのコンピューターに残ります。\n\nGoogle Gemini、Local AI、カスタムを使う場合、Convai のクラウド音声はローカル音声に置き換えられます。音声キーの音声認識は、これらではまだ使えないため、メッセージは入力してください。",
    ["You have used today’s {limit} turns, which come back at {time}. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "今日の {limit} 回の会話を使い切りました。上限は{time}にリセットされます。今すぐ会話を続けるには、Local AI（上限なし）または Google Gemini（ご自身のキーを使用）を選んでください。",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "今日の {limit} 回の会話を使い切りました。上限は明日リセットされます。今すぐ会話を続けるには、Local AI（上限なし）または Google Gemini（ご自身のキーを使用）を選んでください。",
    ["Your changes work with Google Gemini, Local AI and Custom. They do not apply to Convai."] = "変更は Google Gemini、Local AI、カスタムで有効です。Convai には適用されません。",
    ["Your own characters talk only with Google Gemini, Local AI or Custom. With Convai they speak as an ordinary person."] = "自分のキャラクターは、Google Gemini、Local AI、カスタムとだけ会話します。Convai では、普通の人として話します。",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} は自分のキャラクターの一人です。Google Gemini、Local AI、カスタムが必要なので、Convai では普通の人として話します。",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom: choose one under Conversation provider in the settings."] = "{name}はあなた自身のキャラクターの一人です。このキャラクターには Google Gemini、Local AI、Custom のいずれかが必要です。設定の「会話プロバイダー」から1つ選んでください。",
    ["This character needs Google Gemini, Local AI or Custom to answer."] = "このキャラクターが返信するには、Google Gemini、Local AI、またはカスタムが必要です。",
    ["You’ve reached today’s Convai free tier limit. It resets at {time}. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "今日の Convai（無料プラン）の上限に達しました。上限は{time}にリセットされます。今すぐ続けるには、設定 > 会話プロバイダー で別のプロバイダーを選んでください。Local AI は無制限で、お使いの PC で動作します。Google Gemini はご自身のキーで利用できます。",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "今日の Convai（無料プラン）の上限に達しました。上限は明日リセットされます。今すぐ続けるには、設定 > 会話プロバイダー で別のプロバイダーを選んでください。Local AI は無制限で、お使いの PC で動作します。Google Gemini はご自身のキーで利用できます。",
    ["Character bonds"] = "キャラクターとの絆",
    ["Every named character has a bond with you, level 1 to 10. Quests finished together, a romance, eddies paid back and talking raise it; threats and insults lower it. Closer characters trust you more.\n\nA notice shows each level change. Forget clears the talk part. Off by default."] = "名前のあるキャラクターはすべて、あなたとの間にレベル1から10の絆を持っています。一緒に終えたクエスト、恋愛、返済されたエディ、会話で絆は深まり、脅しや侮辱は絆を下げます。親しいキャラクターほどあなたを信頼します。\n\nレベルが変わるたびに通知が表示されます。「記憶を消去」で会話の部分が消えます。初期設定はオフです。",
    ["Bond with {name}: level {level}, {title}"] = "{name}との絆：レベル{level}、{title}",
    ["Bond with {name} fell: level {level}, {title}"] = "{name}との絆が下がった：レベル{level}、{title}",
    ["Acquaintance"] = "顔見知り",
    ["Familiar face"] = "見覚えのある顔",
    ["Friendly"] = "親しみやすい",
    ["Friend"] = "友達",
    ["Good friend"] = "良き友",
    ["Close friend"] = "親友",
    ["Trusted"] = "信頼できる人",
    ["Confidant"] = "腹心",
    ["Family"] = "家族",
    ["Ride or die"] = "一生の味方",
    ["Story packs"] = "ストーリーパック",
    ["When you are close and a character’s own quests are done, they can start a short story of their own. It plays out in talks, texts and calls, and some use Eddies with characters and Immersive invitations.\n\nNeeds Character bonds. Own characters and channels only, never the game’s own scenes or quests. Off by default."] = "親しくなり、キャラクター自身のクエストが終わると、そのキャラクターは自分だけの短いストーリーを始めることがあります。会話、メッセージ、通話の中で進み、一部は「キャラクターとのエディ」や「没入型の招待」を使います。\n\n「キャラクターとの絆」が必要です。対象はあなた自身のキャラクターとチャンネルだけで、ゲーム本来のシーンやクエストには関わりません。初期設定はオフです。",
    ["Characters text first"] = "キャラクターから先に連絡",
    ["Bond: level {level}, {title}"] = "絆：レベル{level}、{title}",
    ["Story: {title}"] = "ストーリー：{title}",
    ["Bonds are not kept while Character bonds is off, so nobody is listed here. Turn it on in Settings, under Companions."] = "「キャラクターとの絆」がオフの間は絆を記録しないため、ここには誰も表示されません。「設定」の「コンパニオン」でオンにしてください。",
    ["Character bonds are off"] = "キャラクターとの絆はオフです",
    ["From their story: {story}, from talking: {talk}"] = "ストーリーから：{story}、会話から：{talk}",
    ["Highest level"] = "最高レベル",
    ["Hurt: {points}"] = "傷つき：{points}",
    ["Hurt: {points}, gone in about a game day"] = "傷つき：{points}、ゲーム内で約1日後に薄れます",
    ["Hurt: {points}, gone in about {days} game days"] = "傷つき：{points}、ゲーム内で約{days}日後に薄れます",
    ["Last talked: today"] = "最後に話したのは：今日",
    ["Last talked: yesterday"] = "最後に話したのは：昨日",
    ["Last talked: {days} days ago"] = "最後に話したのは：{days}日前",
    ["Level {level}"] = "レベル{level}",
    ["No story yet"] = "ストーリーはまだありません",
    ["Nobody yet"] = "まだ誰もいません",
    ["See the characters you have talked to and how close each one is to you: the bond level, what raised or hurt it, their quests and the stories they are in."] = "話したことのあるキャラクターと、それぞれとの親しさを確認できます。絆のレベル、上げたもの・損ねたもの、クエスト、関わっているストーリーが分かります。",
    ["Talk to a character and your bond with them shows here."] = "キャラクターと話すと、そのキャラクターとの絆がここに表示されます。",
    ["The characters you have talked to and how close each one is to you. The most recent come first."] = "話したことのあるキャラクターと、それぞれとの親しさです。新しい順に並びます。",
    ["Their quests: {done} of {total} finished"] = "クエスト：{done}/{total}件完了",
    ["Warmth: {points}"] = "温かさ：{points}",
    ["{points} of {needed} points to level {to}"] = "レベル{to}まで {points}/{needed}ポイント",
    ["{title} (finished)"] = "{title}（完了）",
    ["{title}: {label}"] = "{title}：{label}",
    ["Characters you are close to can text or call you first now and then, and Johnny can speak up in your head. It only happens at calm moments, never in a fight, a scene or a call, and only a few times a day.\n\nNeeds Story packs. Own characters and channels only. Off by default."] = "親しいキャラクターが、ときどき先にメッセージを送ったり電話をかけてきたりします。ジョニーが頭の中で話しかけてくることもあります。落ち着いた場面だけで、戦闘、シーン、通話の最中には起こらず、1日に数回までです。\n\n「ストーリーパック」が必要です。対象はあなた自身のキャラクターとチャンネルだけです。初期設定はオフです。",
    ["Puts every setting on Settings, Romantic relationships, Dynamic info and Key bindings back to its default. Press the button twice to confirm."] = "「設定」「恋愛関係」「リアルタイム情報」「キー割り当て」のすべての項目を初期設定に戻します。ボタンを2回押すと確定します。",
  ["Romantic relationships"] = "恋愛関係",
    ["Add a key first"] = "先にキーを追加してください",
    ["Add a key to choose it"] = "キーを追加すると選べます",
    ["Asks Inworld whether your saved key is accepted. It costs nothing and no speech is made."] = "保存されたキーが受け付けられるかを Inworld に確認します。料金はかからず、音声は生成されません。",
    ["Chosen as the Companion voice"] = "コンパニオンの音声として選択済み",
    ["Connected"] = "接続済み",
    ["Deletes the saved key. If Inworld is your Companion voice, replies show as text until you add a key again."] = "保存されたキーを削除します。Inworld がコンパニオンの音声に設定されている場合、キーを再度追加するまで返答はテキストで表示されます。",
    ["Inworld API key"] = "Inworld API キー",
    ["Inworld cloud voice"] = "Inworldクラウド音声",
    ["Inworld did not accept that key."] = "Inworld がそのキーを受け付けませんでした。",
    ["Inworld is not used with Mature content."] = "Inworld は成人向けコンテンツでは使用されません。",
    ["Inworld voice"] = "Inworld 音声",
    ["Inworld · Cloud voice"] = "Inworld · クラウド音声",
    ["Inworld · needs key"] = "Inworld · キーが必要",
    ["Inworld · not with Mature"] = "Inworld · 成人向け非対応",
    ["Key refused"] = "キーが拒否",
    ["Needs your own Inworld key, from inworld.ai. Inworld’s free plan is a one-time trial of about 70 minutes of speech, then you pay as you go.\n\nCopy your key first, then press Add. It is read from the clipboard once, checked with Inworld and saved on this computer."] = "inworld.ai で取得した、ご自身の Inworld キーが必要です。Inworld の無料プランは約70分の音声を使える一度きりのお試しで、その後は使った分だけ支払います。\n\nまずキーをコピーしてから「追加」を押してください。キーはクリップボードから一度だけ読み取られ、Inworld で確認されたうえで、このコンピューターに保存されます。",
    ["Not reachable"] = "接続できません",
    ["Not used with Mature content"] = "成人向けでは未使用",
    ["Ready to choose in Companion voices"] = "コンパニオンの音声で選択できます",
    ["Requires an Inworld key (add it in Settings > Voices > Custom voices)"] = "Inworld キーが必要です（設定 > 音声 > カスタムボイス で追加）",
    ["Speaks each companion in their own voice, on your own Inworld key. English only. Choose it under Companion voices, where it is listed last once a key is added."] = "各コンパニオンをそれぞれの声で話させます。ご自身の Inworld キーを使用します。英語のみ。コンパニオンの音声で選択でき、キーを追加すると一番下に表示されます。",
    ["{voice} · needs Inworld key"] = "{voice} · Inworld キーが必要",
    ["Choose a character to start editing."] = "編集するキャラクターを選択してください。",
    ["Clear search"] = "検索をクリア",
    ["Companion"] = "コンパニオン",
    ["Companions"] = "コンパニオン",
    ["Custom voice"] = "カスタムの声",
    ["Close"] = "閉じる",
    ["In front of you"] = "目の前",
    ["You have switched off as many people as the editor keeps ({max}). Switch one back on first."] = "エディターが保持する数（{max}）と同じだけの人を無効にしました。まず一人を有効に戻してください。",
    ["That person cannot be switched off."] = "その人は無効にできません。",
    ["Don’t talk to this character"] = "このキャラクターと話さない",
    ["While this is on, they do not answer you and never join a group chat. Untick it to talk to them again."] = "これが有効な間、彼らは返答せず、グループチャットには参加しません。再び話すには、これをオフにしてください。",
    ["Switched off."] = "無効にしました。",
    ["Switched back on."] = "有効に戻しました。",
    ["Switch back on"] = "有効に戻す",
    ["Don’t talk to this person"] = "この人と話さない",
    ["It also stops everyone the game builds from the same record, so other people of the same kind may stop answering too."] = "同じレコードからゲームが構築するすべての人を停止します。そのため、同じ種類の他の人も答えを止める可能性があります。",
    ["Switched off"] = "無効",
    ["People and characters you chose not to talk to. Switch one back on to talk to them again."] = "話さないと決めた人とキャラクター。一人を有効に戻して、再び話してください。",
    ["Recently edited"] = "最近編集",
    ["Romance"] = "ロマンス",
